V = set("AEIOU")

def learn_vc(examples):
    dv, dc = set(), set()
    for w, c in examples:
        for a, d in zip(w, shifts(w, c)):
            (dv if a in V else dc).add(d)
    assert len(dv) == 1 and len(dc) == 1
    return dv.pop(), dc.pop()

def code(examples, target, options):
    assert learn(examples) is None          # one shift for all letters fails
    v, c = learn_vc(examples)
    out = "".join(L(P(ch) + (v if ch in V else c)) for ch in target)
    return (v, c), [lab for lab, x in options.items() if x == out]

# worked example 2024-09-09_1600_R16: consonants +1, vowels unchanged
assert code([("SILK", "TIML"), ("INSECT", "IOTEDU")], "CHANGE",
            {"A": "DEIHAO", "B": "DOIHAE", "C": "DIAOHE", "D": "DEIOHA"}) == ((0, 1), ["C"])
